-- Release notes shown in the in-client What's New window.
--
-- GENERATED by Scripts/build_release_notes.py from CHANGELOG.md. Do not edit
-- by hand: tests/python/test_release_notes.py re-runs the generator and
-- compares, so a hand edit fails the suite rather than surviving in it.
--
-- ENGLISH ONLY, DELIBERATELY. The window's chrome is localized; the document
-- inside it is not -- these strings carry no Locales/ entry and never will.
--
-- ONLY THE NEWEST 5 RELEASES ARE HERE. An older version's notes are
-- gone, not missing: CHANGELOG.md still has them, this table never will.
--
-- `lead` IS OPTIONAL. It is a bullet's bold prefix, where the source bullet
-- had one; 0 of the 64 items below have none, so a consumer
-- must not assume every item carries one.
--
-- `sep` IS THE SEPARATOR THE CHANGELOG WROTE between a lead and the rest of
-- the bullet -- an em dash or a colon, recorded rather than dropped. ABSENT
-- MEANS THE SOURCE WROTE NEITHER, not that one went missing: 63 of the
-- 64 leads below have no `sep`, and supplying one for those strands a
-- predicate with nothing in front of it ("BatchSell -- now asks ...").
--
-- 5 releases, 64 items, v12.1.0.12 down to v12.1.0.8.

---@class BitForge.Core
local ns = select(2, ...)

---@type BitForge.Core.Enum
local enum = ns.enum

enum.RELEASE_NOTES = {
    {
        version = "v12.1.0.12",
        date = "2026-09-04",
        sections = {
            {
                heading = "Added",
                items = {
                    { lead = "BitForge now tells you when one of its addons has fallen out of step with the rest.", text = "Six separate downloads means your addon manager can update one and leave another behind, which nothing used to be able to notice. When it happens, BitForge says so once in chat as you log in, naming the one to go and fetch -- and then stays quiet until the versions change again." },
                },
            },
            {
                heading = "Changed",
                items = {
                    { lead = "BitForge is six separate downloads now, one for each addon.", text = "The core and its five modules used to arrive in a single zip; each is its own CurseForge project from here on, updated on its own. Nothing is removed when you update, so every folder you already have stays where it is and keeps working -- but the BitForge download no longer updates the five modules, and your addon manager has no project to match those folders to. Install the ones you use as their own projects, and the old folder is safe to delete once its replacement is in place." },
                    { lead = "Dispatch is now AzerothPrime, and everything you had set comes with it.", text = "Install BitForge AzerothPrime where you had BitForge_Dispatch: your rules, per-item lists, curation destinations, blacklists and the button's size and position all move across on their own, and there is nothing to re-enter. If the old Dispatch is still installed, AzerothPrime switches it off first and your settings arrive at your next login -- so finding Dispatch greyed out in the addon list is expected rather than a fault, and the folder is safe to delete then." },
                    { lead = "Your keybinding for the openables button does not come with it.", text = "The game stores a keybinding under the button's name, and the button's name changed with the addon's, so yours is cleared. Set it again in the standard Key Bindings panel." },
                    { lead = "Every BitForge window has been retuned, and text is easier to read.", text = "Body text was a mid-grey that sat closer to the background than to white; it is near-white now, and the old grey survives only where something is deliberately dimmed. Window borders were darker than the panel they outlined, which read as a gap rather than an edge -- they are lighter than it now. Buttons are slightly shorter so they line up with the dropdowns and text boxes they share a row with, checkboxes slightly taller so the box has room to breathe, and the report window is a little larger with more space inside it. Windows also now refuse to be dragged smaller than they can usefully be drawn." },
                    { lead = "The close button is an X inside a square outline.", text = "It was two loose strokes, which read as a smudge at the small size. The button is the same size, sits in the same place and responds the same way; only the mark inside it changed, and it is drawn larger relative to the button so it holds up at every size." },
                    { lead = "EllesmereUI's skinning switch is now per addon rather than one switch for all of BitForge.", text = "The suite registered itself under a single name, so turning its skinning on or off in EllesmereUI applied to every BitForge window at once. Each addon now registers under its own name, which is what EllesmereUI's per-addon toggle was always keyed to -- so you can keep AzerothPrime skinned and leave RepRank alone, or any other combination. Nothing changes if you do not use EllesmereUI." },
                    { lead = "The EllesmereUI editor's close button is the suite's own now.", text = "It was the only window in BitForge still using Blizzard's close button, which is why it never quite matched the others. It does now." },
                    { lead = "A slightly smaller download.", text = "Four pieces of artwork that nothing had drawn for some time were still being packaged into every release, and so were the development files of the UI toolkit BitForge embeds. Both are gone." },
                },
            },
            {
                heading = "Fixed",
                items = {
                    { lead = "Flagging a recipe now keeps every reagent it needs, not just the ones BitForge already had on file.", text = "Flagging reads the recipe's ingredient list from the game, but a second check sat in front of it: a list of \"which professions use this item\", built by hand and shipped with the addon. Anything that list had not heard of -- most obviously anything added since it was last rebuilt -- was sold anyway, so the flag quietly did nothing for those reagents. It no longer has a say when the game has already answered. Nothing changes for a reagent the list does know about: flagging still does not override which of your characters can actually reach and use the item." },
                },
            },
        },
    },
    {
        version = "v12.1.0.11",
        date = "2026-09-03",
        sections = {
            {
                heading = "Added",
                items = {
                    { lead = "Flag a recipe, and Dispatch keeps what it is made of.", text = "Right-click a recipe in your profession window and there is a Flag entry on the menu: from then on, every reagent that recipe consumes is kept even when the reagent rule would otherwise let it go. It reads the recipe's own ingredient list from the game, so nothing has to be listed by hand and a flag keeps working when the recipe's requirements change. Basic ingredients only -- an optional or finishing reagent is not covered, because those are a choice you make at the crafting window rather than something the recipe needs." },
                    { lead = "The expansion lists have a Vanilla row.", text = "Items the game files under the original game had no row to tick, so no expansion list could name them. They can be named now, everywhere an expansion list appears. One quirk worth knowing, and it is the game's rather than ours: a few items sold across late Vanilla and early Burning Crusade report the current expansion instead of either of them, so those follow the Current expansion row rather than Vanilla." },
                    { lead = "The openables button offers you a cosmetic whose appearance you have not collected.", text = "These grant the appearance when you use them rather than when you vendor them, so one sitting unused in your bags is an appearance you do not have — and the button never showed them. It could not: an item says it adds an appearance on a line the game gives no type to, indistinguishable from any other sentence in a tooltip, and the two items that do have a type are ensembles and illusions. It now asks the collection directly instead, and a single uncollected appearance ranks with recipes and toys as something to learn. Once it is collected the item drops off the button again." },
                },
            },
            {
                heading = "Changed",
                items = {
                    { lead = "/bfdump is a developer's command now, and a released build answers none of it.", text = "/bfdump openables and /bfdump batchsell opened a machine-readable record of what BitForge had concluded about an item; Dispatch inherits neither of them, and /bfdump eui goes the same way. None of them is listed by /bitforge any more, and typing one is refused. If you ever pasted one of those records into an issue, that is a real loss and worth saying plainly rather than leaving you to find it. What is not lost is the record itself: Shift+Alt+right-click on the openables button, and Report This Verdict on an item at a vendor, open the same window they always did with the same report in it -- already selected, nothing written to your saved variables, no reload, and still saying what it discloses before you send it." },
                    { lead = "Reagents are now kept by expansion first, and by the recipes you flagged second.", text = "The rule used to be one question -- does one of your professions craft with this -- and it kept the answer whatever expansion the reagent came from. It is two questions now: keep it if its expansion is ticked, otherwise keep it if a recipe you flagged wants it, otherwise sell it. The list starts on Current expansion, and your existing profile moves to that default rather than being migrated to something wider. So expect older reagents to be offered for sale even if you change nothing -- everything from a finished expansion that no flagged recipe consumes. If you were relying on the old behaviour, tick All expansions in the reagent rule, or flag the recipes you are actually saving them for." },
                    { lead = "Every rule that names expansions now agrees about the original game.", text = "The two questions behind the expansion lists both treated an item from the original game as though the game had not answered, which meant a Vanilla piece slipped past the rules that were supposed to weigh it. This was not confined to reagents: it reaches the Bind on Equip and Bind on Account gear rescues and the keep-it-to-disenchant question too. Those rules now decide about a Vanilla item rather than stepping around it, so a Vanilla piece may be sold where it previously survived, and kept where you have ticked Vanilla." },
                    { lead = "An item in your bags now gets one answer instead of three.", text = "The openables button, the vendor sweep and the Warband deposit each decided on their own, so the same item could sit on the button and in the sell list at once, and whichever you clicked first won. They agree now, and opening comes first -- it is the only one of the three that turns an item into other items, so a box you sold is gone while a box you opened is sorted out on the next pass. Four things follow: a cache or container is opened rather than sold; a recipe another of your characters still needs is kept; a recipe you have not learned but do not want stops being offered on the button and in the sell list at the same time; and with Only wanted reagents off, a reagent bound for the bank is no longer offered to the vendor as well. Grey items with a \"Use:\" line are the deliberate exception and still sell -- \"the game says this does something\" is not a reason to keep vendor trash." },
                    { lead = "Your own decisions about an item are stored in one place instead of three.", text = "Hiding something from the openables button, putting it on a sell list, and choosing which bank it belongs in were three separate records, kept by what used to be three separate addons. They are one record now, and everything you had set is carried across the first time you log in — nothing is reset and there is nothing to re-enter. You should not be able to tell the difference from playing; that is the intent. One consequence worth knowing: once this version has upgraded your saved data, an older version of Dispatch can no longer read it, so this is not a change to roll back from by reinstalling an earlier build." },
                    { lead = "Openables, Batch Sell and UPS are now one addon: Dispatch.", text = "Three folders become one, and the three features become three switches inside it — the openables button, selling at a vendor, and depositing to the Warband Bank — each turned on and off on its own in the settings panel. Everything you had configured in all three is carried over the first time you log in: rules, per-item lists, curation destinations, blacklists, the button's size and position. Nothing is reset and there is nothing to re-enter. One thing does not survive the move: the keybinding for the openables button. The button's name changed with the addon's, and the game stores keybindings by name, so yours is cleared — set it again in the standard Key Bindings panel. If you install by hand rather than through an addon manager, delete the three old folders: Dispatch refuses to start while any of them is still installed, and tells you which." },
                    { lead = "Every selling rule that asked about an expansion now lets you name the expansions.", text = "The three-way \"this expansion / all of them / none\" on the gear rescues, and the \"keep this expansion's\" checkboxes on consumables, gems, reagents and enhancements, are one control now: a list you tick. Keep Dragonflight's flasks and nothing older, or spare Bind on Equip gear from the two expansions you are still levelling alts through. Each list opens with \"All expansions\" and \"Current expansion\", which follow the game as it moves, while a named expansion stays the one you picked. Two limits go with the old shape: consumables offered only the expansion immediately behind, and only while \"this expansion\" was ticked, and enhancements always kept the current expansion whether you wanted them or not. Your existing settings all carry across — nothing is reset." },
                    { lead = "Selling trusts the crafting-reagent list instead of hedging against it.", text = "The list is captured from the game's own recipes, and anything missing from it used to count as \"unknown\" rather than as an answer — so an item it had never heard of was held back rather than judged, whatever you had set. That was meant to protect reagents, and mostly it protected junk: the list does know the real reagents, so those were already being handled correctly, while last expansion's food, gems and trade goods it had never seen sat in your bags forever with no setting that could shift them. Absence now means what it reads as — nothing crafts with this — and those items go through your rules like anything else. Expect more to be offered for sale, in the consumables, gems and trade goods rules especially. Your Never Sell list still overrules everything, and the reagent list is retaken from the client and reshipped after a game patch." },
                    { lead = "Eight retired items no longer appear on the openables button.", text = "A Draenor cache, two Legion tomes and a set of War Within delve rewards are all grey, which is how the game marks this kind of item as finished with, and the button's curated list no longer overrides that — so the next one Blizzard retires drops off on its own rather than waiting for someone to notice." },
                },
            },
            {
                heading = "Fixed",
                items = {
                    { lead = "A greyed-out dropdown now looks greyed out.", text = "Every BitForge dropdown that switches itself off when another setting has already decided the question was painting only half of itself as disabled -- the arrow and the frame dimmed, the text stayed bright -- so a control that was doing nothing still read as live. It has been shipping that way in TaskTome and EUI as well as here, and all three are fixed together." },
                    { lead = "The report windows now say exactly what they carry.", text = "The footnote under the openables report named the item, how BitForge classified it, its tooltip and this character's professions -- but not the bag and slot it was sitting in or whether it was locked, both of which the report also prints. The sell verdict's footnote was short of fields in the same way. So a report pasted into a public issue carried a little more than its own footnote promised. Both now list everything they disclose, and what you are told you are sending is what you send." },
                    { lead = "The selling rules stop short of an item the game will not describe.", text = "An item's quality can be missing for a moment while the game is still answering, or withheld by the game outright — and only the first of those was being recognised. The selling rules and the disenchant probe now recognise both, and treat such an item as unanswered rather than weighing it against your settings on a quality nobody ever gave them." },
                    { lead = "The openables button no longer acts on an item before the game has finished describing it.", text = "An item's tooltip and its item data load separately, and for a moment after a bag changes the tooltip can be empty. The button read that silence as an answer -- it took \"no line said this item cannot be used\" from a tooltip it had not been shown -- so in that moment it could offer an item the game itself refuses, and a toy or a recipe could be ranked below whatever else you were carrying instead of at the top. It now waits, and the item appears as soon as the tooltip arrives. If you are used to something showing up the instant it drops, it may now take a fraction of a second longer." },
                    { lead = "Moving the openables button no longer skips the item on it.", text = "Alt and left-drag is how you reposition the button, and the same press was also counted as using the item -- so the item you were carefully not touching went to the back of the queue and the button moved on to the next one. It never actually opened anything: the game only performs a button's action on an unmodified click, so holding Alt meant nothing happened at all except the wrong bookkeeping. Holding Shift or Ctrl on a left click had the same effect and nobody had noticed. All three now leave the item where it is." },
                    { lead = "The openables button no longer offers you socket gems.", text = "A gem's stats are built as an enchantment, and that is indistinguishable to an addon from an ordinary \"Use:\" effect — so every gem sitting in your bags took its turn on the button as though it were something to open. A gem goes into a socket rather than opening anything, and they are now left out." },
                },
            },
        },
    },
    {
        version = "v12.1.0.10",
        date = "2026-08-30",
        sections = {
            {
                heading = "Fixed",
                items = {
                    { lead = "The CurseForge download works again.", text = "v12.1.0.8 and v12.1.0.9 were built and uploaded, and CurseForge refused both of them while processing the file — so the newest version there is still v12.1.0.7, and everything those two releases carried has been sitting somewhere CurseForge could not hand it to you. The package was shipping a documentation folder belonging to a bundled library, which CurseForge will not accept in an addon. The Wago and GitHub downloads were unaffected and have had both releases all along." },
                },
            },
        },
    },
    {
        version = "v12.1.0.9",
        date = "2026-08-30",
        sections = {
            {
                heading = "Changed",
                items = {
                    { lead = "BitForge has a mark of its own.", text = "The minimap button was wearing the game's engineering icon, and the addon list and the addon compartment entry showed nothing at all — the icon the addon claimed to carry had never been drawn. All three now show the suite's own." },
                },
            },
        },
    },
    {
        version = "v12.1.0.8",
        date = "2026-08-27",
        sections = {
            {
                heading = "Changed",
                items = {
                    { lead = "/bfdump batchsell opens a window you can copy out of.", text = "It used to write its record into the saved variables, so getting it to us meant setting a debug flag by hand, running the command, reloading, opening SavedVariables/BitForge.lua in a text editor and pasting a Lua table — which is why almost nobody ever did. It now renders the record straight into the same window the report button uses: select, copy, paste. Nothing is written to disk, so the diagnostics flag no longer has to be on for the command to answer, and each report still states what it discloses before you send it. The other modules follow." },
                    { lead = "Every /bfdump now opens that window", sep = "—", text = "Openables and the EllesmereUI helper as well as BatchSell, and each with its own footnote saying what that particular report discloses. A diagnostic dump opens under its own title rather than borrowing the item report's, since a bag's ranked list or a frame's position is not an item. /bfdump dev recipes is the one exception and keeps writing to the saved variables: a whole profession is a quarter of a megabyte, and it exists to be carried out of the game as a file rather than read." },
                    { lead = "A diagnostic too long to read is compressed instead.", text = "The bag-walking dumps run to hundreds of lines of tooltip text nobody was ever going to read — just select and paste. Above a few thousand characters the window now shows a single compressed line instead, and the footnote says so: paste it exactly as it is and the developer's tools unpack it. Reports short enough to read are untouched and stay readable, which is the whole point of the window." },
                    { lead = "The report window stays where you put it.", text = "Drag it somewhere that suits your screen and it opens there next time, for every character on the account. It only remembers the report window — the What's New popup still opens where it always did." },
                    { lead = "BatchSell sells a toy once you have collected it.", text = "Mounts, battle pets and housing decor were already judged on whether your collection has them; toys were the one kind left out, so a toy already in your toy box sat in your bags forever. It is sold only once the copy in your bags is bound — an unbound one is kept whatever your collection says, because it can still reach someone who wants it. On by default, and switchable in the Rules window beside the other three." },
                    { lead = "BatchSell's gear comparison now has two dials instead of one.", text = "\"Item Level Margin\" was named for item levels but priced a quality tier, and \"Emphasize Quality\" doubled it and granted a tolerance of the same size — one slider doing two jobs, and a checkbox you could not have one without the other of. They are replaced by a margin, which is how far under the slot a piece of your own quality may sit, and a quality margin, which is what one quality tier is worth in item levels. Either can be set to 0 on its own: no tolerance, or quality stops counting and item level alone decides. Your existing settings for these two are reset to the new defaults, which reproduce the comparison BitForge shipped with — so if you never touched them, nothing changes. If you had raised the old margin, gear a quality tier above what you wear will now be sold more readily than before until you set the quality margin back where you want it." },
                    { lead = "And the two checkboxes above them are gone.", text = "\"Compare Item Level\" and \"Compare Quality\" have left the Rules window, so the two dials are now the whole of the comparison. The first only said whether the two sliders beside it applied at all, and its own description was wrong about what turning it off did; the second sold any piece of lower quality than what you have equipped, whatever its item level. If you had either set away from its default, gear will be judged differently for you from now on — the item level comparison can no longer be switched off, and instead of an outright quality veto a lower quality piece now has to make the difference up in item levels, at the price the quality margin sets. If you left both alone, nothing changes." },
                    { lead = "BatchSell's quality margin gained an \"Always\" setting.", text = "Past the top of the slider there is now one more position, and it is not a number of item levels: set there, gear of a higher quality than what you have equipped is kept whatever its item level, and no amount of item level saves a piece of lower quality. It is the outright quality preference the retired \"Compare Quality\" tick used to give, now on the same dial as everything else it competes with. The slider also runs to 30 rather than 20, matching the item level margin beside it." },
                    { lead = "Gear that matches what you are wearing is kept rather than sold.", text = "Every item level comparison in the rule was \"strictly better\"; it is now \"at least as good\". At the default margin of 0, a piece level with the slot is kept instead of vendored, and a piece a tier below only has to make the quality margin up exactly rather than exceed it. Quality itself is unchanged — this is about item levels alone." },
                    { lead = "A piece from a finished expansion is now weighed by the same two dials as anything else.", text = "BitForge v12.1.0.7 said the opposite — that such a piece \"sets its bar on item level alone, no margin, no quality discount\" — and that is withdrawn. There is one comparison in the rule again, and what a finished-expansion piece still changes is the reason you are told: the tooltip says you outlived that bar rather than merely beat it. If you are levelling in last expansion's gear, expect this to matter: at the shipped defaults, this expansion's rare has to beat a finished-expansion epic by the quality margin rather than by a single item level. Setting the quality margin to 0 restores the v12.1.0.7 behaviour, for every comparison rather than only that one." },
                    { lead = "German now addresses you the way the game does.", text = "The client is consistently formal — Eure Taschen sind voll — and BitForge was mixing that with the familiar du, sometimes inside a single window: BatchSell's settings block was formal while the rule window beside it was not." },
                    { lead = "Each module keeps its name in every language.", text = "Openables, RepRank, Task Tome, AutoBalance and Undermine Parcel Service were being translated as though they were descriptions, which is how UPS ended up named after Undercity in French, Azeroth in Chinese and Kaz'Mina in Portuguese — three places, none of them Undermine." },
                    { lead = "BatchSell stops calling one thing two names inside a single language.", text = "Mexican Spanish used two different verbs down one column of checkboxes; Russian split quality between two words and crafting between two more; Chinese had two words for collecting and two for artifact relics; Portuguese, Italian and Traditional Chinese each named dyes, decor or holiday items differently in the settings than in the rules that describe them." },
                    { lead = "BatchSell speaks the game's own vocabulary in every language.", text = "A Russian setting told you to turn it on under exactly the condition it should be left off. Korean named the sell-list tab and the always-sell tab identically, called Skinning by a word the game does not use, and described item enhancements as arcane power. Six languages narrowed \"enhancements\" to enchants alone, contradicting the line directly above them. Chinese called heirlooms \"retro\", used patch where it meant expansion, and used the verb for reporting a player to Blizzard. Spanish called crafting reagents chemical reagents, in three different ways within one file. Around ninety strings in all." },
                    { lead = "The report window and the minimap hint say the right thing in Chinese, German and Russian.", text = "The Chinese title used the verb for reporting someone to the authorities, the German instructions named a key German keyboards do not have (Ctrl, not Strg), and the Russian minimap hint pointed at the wrong word for settings. French now names its own button correctly in the line above it." },
                    { lead = "AutoBalance:", text = "the gold target says \"your bags\" in the words each client uses for bags, and the Russian checkbox reads as a setting to turn on rather than a section heading." },
                    { lead = "Openables in Portuguese no longer reads as though it destroys things.", text = "Blacklisting was worded with the verb the game uses for delete, so \"Ctrl + right-click to permanently exclude\" invited exactly the wrong reading. Spanish, French and Chinese also get the module's own name and its report wording corrected." },
                    { lead = "TaskTome in Russian calls a task a task.", text = "It used the word the Russian client reserves for quests, which made every tracked item look like one." },
                    { lead = "BatchSell:", text = "the two Bind on Account / Bind on Equip sparing settings explain themselves. They described \"unbound Bind on Account gear\", which reads in English only because Bind on Account is a name — every other language rendered it as \"unbound bound gear\". They now say what the state is: gear kept while it can still be passed on." },
                    { lead = "The Warband is called what the game calls it", text = ", in every language and every module. Ten of the eleven locales had invented their own word for it, and several used a different invention in each module — Korean alone had three (워밴드, 전투부대, 전쟁부대) for the one thing the game calls 전투부대. The names now match what you read on the bank itself." },
                    { lead = "BatchSell:", text = "the German and Italian Rules window no longer names one thing two ways — the line listing recipe types and the explanation under it used different words for \"pattern\", on two lines that sit next to each other." },
                    { lead = "BatchSell:", text = "in the Rules window, \"Keep this expansion's unless no recipe wants it\" now greys out while \"Keep everything from this expansion\" is ticked above it — for consumables and for gems alike. It could be ticked before and changed nothing, because the broader rule had already kept the item." },
                },
            },
            {
                heading = "Fixed",
                items = {
                    { lead = "Keeping gear for an enchanter now asks what it would turn into.", text = "\"Keep Disenchantable Gear\" was on-or-off, so a Classic-era green was kept forever by a rule whose whole argument is that somebody wants the materials — and nobody wants those. It becomes a choice of current materials, any materials, or don't keep, worded about the materials because that is what a disenchant actually gives you: gear from a finished expansion yields that expansion's materials, however current its item level looks. Your existing setting is carried across unchanged — if it was on you keep everything, exactly as before, until you narrow it yourself. A new character starts on current materials. Your own enchanter still keeps what only they can reach at any setting; what this decides is whether that reaches older materials too." },
                    { lead = "Warband gear you have already equipped is no longer treated as though an alt could still take it.", text = "A Warbound piece moves freely between your characters until you equip it, and equipping binds it for good — but BatchSell was still reading it as account-bound afterwards, so a worn piece was kept for an alt's enchanter, and a bound Warbound reagent was weighed against every profession on the account rather than the one holding it. Once something is bound, it is bound." },
                    { lead = "BatchSell no longer sells a bound piece when the game has not said whether it is Warbound.", text = "The three rules that keep gear for somebody else each worked out separately whether a copy could still leave you, and one of them read an unanswered question as a no — so a soulbound item the game had not finished describing could be vendored as outclassed. There is one answer to that question now, and where it cannot be answered nothing is sold on it." },
                    { lead = "Openables:", text = "the button stops flickering past an item when what you clicked has a cast time. Clicking it moved the button on, and then moved it on again when the cast finished — so the item it showed in between was never really offered. It now holds still until the use resolves and moves on once." },
                    { lead = "Openables:", text = "an item you cannot use yet is not offered. Something waiting on a part you have not looted, a level you have not reached or a currency you have not saved was being put on the button on nothing more than the fact that it does something — an egg that combines with a second half you do not have, for instance. It appears the moment it becomes usable. Items recognised for what they are rather than for having a use — toys, recipes, appearances, anything that opens — are unaffected." },
                    { lead = "Openables:", text = "a toy you have not collected yet is offered as something to learn. One whose tooltip describes what it does rather than announcing itself as a toy — a teleport key, say — was being read as junk and hidden. Once it is in your toy box it goes back to being hidden, since the copy in your bags has nothing left to give." },
                    { lead = "Openables:", text = "profession knowledge items appear again. They had stopped, because the client reports every profession in the game at rank zero when asked by skill line — including the ones your character actually has — so nothing could be recognised as yours. The rank now comes from the API that states it." },
                    { lead = "Openables:", text = "thirteen more items that were never openable stop appearing on the button — a guild banner, a cooking bell, a conduit, a music roll, a blink vial and the rest of one player's report. They are listed by name rather than caught by a rule, because any rule wide enough to catch them would also hide the conduits and reputation tokens they sit beside." },
                    { lead = "Openables:", text = "gadgets stay off the button — repair bots, target dummies, time displacers, remote auction house access and the rest of the category the game files them under. The handful of real containers that share it are unaffected." },
                    { lead = "Openables:", text = "baits, lures and other profession tools stay off the button whether or not your character has learned the profession. One gated on a profession you do not have was offered as something to open — the case where it is least useful, since you cannot use it at all." },
                    { lead = "Openables:", text = "a character who has learned no professions is no longer offered every oddment in their bags as something to study." },
